<template>
  <view class="page">
    <map class="map" :latitude="center.latitude" :longitude="center.longitude" :markers="markers" :polyline="polyline" :scale="15"></map>
    <view class="top" :style="{paddingTop:statusBar+'px'}"><view class="round" role="button" aria-label="返回" @tap="back"><view class="back"></view></view><text>{{ config.title }}</text><view class="round" role="button" aria-label="预约说明" @tap="showHelp"><view class="info">i</view></view></view>
    <view class="place-chip"><view class="pin"></view><view><text>{{ service.title }}</text><text>{{ service.address }}</text></view><text>{{ service.distance }}km</text></view>
    <view class="panel">
      <view class="handle"></view><view class="panel-head"><view><text>{{service.categoryName}}</text><text>{{service.verification.label}} · 营业中</text></view><text class="total">¥{{total}}</text></view>
      <text class="label">{{config.parameterLabels[0]}}</text><view class="counter"><view @tap="change(-1)">−</view><text>{{quantity}} {{config.unit}}</text><view @tap="change(1)">＋</view></view>
      <text class="label">服务规格</text><scroll-view scroll-x :show-scrollbar="false"><view class="packages"><view v-for="item in service.packages" :key="item.id" :class="{active:packageId===item.id}" @tap="packageId=item.id"><text>{{item.name}}</text><text>¥{{item.price}}</text></view></view></scroll-view>
      <text class="label">{{config.parameterLabels[1]}}</text><view class="duration"><view v-for="value in durationOptions" :key="value" :class="{active:duration===value}" @tap="duration=value">{{value}}{{service.serviceCategory==='ticket'?'场':'小时'}}</view></view>
      <view class="route"><view class="route-line"></view><view><text>从 · 我的位置</text><text>到 · {{service.venue.name}}</text></view><text>约 12 分钟</text></view>
      <view class="confirm" @tap="confirm"><text>{{config.action}}</text><view></view></view>
    </view>
  </view>
</template>
<script setup>
import { computed, ref } from 'vue'; import { onLoad } from '@dcloudio/uni-app'; import { calculateSelectionTotal, normalizeService, SERVICE_CATEGORY_CONFIG } from '../../utils/serviceCatalog.js'
const statusBar=ref(20),quantity=ref(1),duration=ref(1),packageId=ref(''),service=ref(normalizeService({},'food'))
const config=computed(()=>SERVICE_CATEGORY_CONFIG[service.value.serviceCategory]);const durationOptions=computed(()=>service.value.bookingConfig.durationOptions||[1,2,3]);const total=computed(()=>calculateSelectionTotal(service.value,{packageId:packageId.value,quantity:quantity.value}));const coords=computed(()=>service.value.location.coordinates);const center=computed(()=>({longitude:coords.value[0],latitude:coords.value[1]}));const markers=computed(()=>[{id:1,longitude:coords.value[0],latitude:coords.value[1],width:34,height:42,iconPath:'/static/marker-green.png',callout:{content:service.value.title,color:'#171c1b',bgColor:'#ffffff',padding:8,borderRadius:8,display:'ALWAYS'}}]);const polyline=computed(()=>[{points:[{longitude:coords.value[0]-.006,latitude:coords.value[1]-.004},{longitude:coords.value[0],latitude:coords.value[1]}],color:'#3182F6',width:5,dottedLine:true}])
onLoad(options=>{const raw=uni.getStorageSync('BOOKING_ITEM')||uni.getStorageSync('SERVICE_LAST_ITEM')||{};service.value=normalizeService(raw,options.category);packageId.value=raw.selectedPackage?.id||service.value.packages[0].id;quantity.value=Number(raw.people||1);try{statusBar.value=(uni.getWindowInfo?.()||uni.getSystemInfoSync()).statusBarHeight||20}catch(e){}})
function change(delta){quantity.value=Math.min(service.value.bookingConfig.maxQuantity,Math.max(service.value.bookingConfig.minQuantity,quantity.value+delta))}function back(){uni.navigateBack()}function showHelp(){uni.showModal({title:'参数说明',content:service.value.highlights.join('\n'),showCancel:false})}function confirm(){const carry={...service.value,selectedPackage:service.value.packages.find(i=>i.id===packageId.value),selectedDuration:duration.value,people:quantity.value};uni.setStorageSync('BOOKING_ITEM',carry);uni.setStorageSync('SERVICE_LAST_ITEM',carry);uni.navigateTo({url:`/pages/booking/index?source=params&id=${encodeURIComponent(service.value.id)}&category=${service.value.serviceCategory}`})}
</script>
<style scoped>
.page{position:relative;height:100vh;overflow:hidden;background:#dfe9e6}.map{position:absolute;inset:0;width:100%;height:66vh}.top{position:absolute;z-index:3;left:16px;right:16px;top:0;padding-bottom:12px;display:flex;align-items:center;justify-content:space-between}.top>text{font-size:18px;font-weight:800}.round{width:48px;height:48px;border:1px solid rgba(255,255,255,.86);border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.88);box-shadow:var(--shadow-float);backdrop-filter:blur(10px)}.back{width:10px;height:10px;border-left:2px solid var(--color-text);border-bottom:2px solid var(--color-text);transform:rotate(45deg)}.info{width:18px;height:18px;border:2px solid var(--color-text);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800}.place-chip{position:absolute;z-index:3;left:20px;right:20px;top:24%;padding:11px 14px;border-radius:18px;display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.9);box-shadow:var(--shadow-float)}.pin{width:14px;height:14px;border:4px solid var(--color-primary);border-radius:50%}.place-chip>view:nth-child(2){flex:1}.place-chip text{display:block}.place-chip>view text:first-child{font-weight:800}.place-chip>view text:last-child{margin-top:3px;color:#78827f;font-size:11px}.place-chip>text{font-size:12px}.panel{position:absolute;z-index:4;left:12px;right:12px;bottom:calc(10px + env(safe-area-inset-bottom));max-height:69vh;padding:10px 18px 18px;border-radius:28px;background:rgba(26,34,35,.88);color:#fff;box-shadow:0 -24px 54px rgba(0, 0, 0, 0.1);backdrop-filter:blur(10px);overflow:auto}.handle{width:42px;height:5px;margin:0 auto 12px;border-radius:5px;background:rgba(255,255,255,.36)}.panel-head{display:flex;align-items:flex-end;justify-content:space-between}.panel-head text{display:block}.panel-head>view text:first-child{font-size:19px;font-weight:800}.panel-head>view text:last-child{margin-top:4px;color:#b8c4c1;font-size:11px}.total{color:#71e0d2;font-size:24px;font-weight:850}.label{display:block;margin:16px 0 9px;color:#c9d3d1;font-size:12px;font-weight:700}.counter{height:50px;border-radius:16px;display:flex;align-items:center;justify-content:space-between;background:rgba(255,255,255,.09)}.counter view{width:50px;height:50px;display:flex;align-items:center;justify-content:center;font-size:24px}.counter text{font-size:18px;font-weight:800}.packages{display:inline-flex;gap:9px}.packages view{min-width:118px;padding:11px;border:1px solid rgba(255,255,255,.13);border-radius:14px;background:rgba(255,255,255,.06)}.packages text{display:block}.packages text:first-child{font-weight:700}.packages text:last-child{margin-top:5px;color:#9ca8a5;font-size:11px}.packages .active{border-color:#71e0d2;background:rgba(32,32,32,.18)}.duration{display:flex;gap:8px}.duration view{flex:1;height:42px;border-radius:13px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.08)}.duration .active{background:#fff;color:var(--color-text);font-weight:800}.route{margin-top:16px;padding:12px;border-radius:15px;display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.07)}.route-line{width:3px;height:32px;border-radius:3px;background:#3182F6}.route>view:nth-child(2){flex:1}.route text{display:block;font-size:11px}.route>view text:last-child{margin-top:6px}.route>text{color:#aeb9b6}.confirm{height:54px;margin-top:14px;border-radius:17px;display:flex;align-items:center;justify-content:center;gap:10px;background:var(--gradient-primary);font-weight:800}.confirm view{width:9px;height:9px;border-top:2px solid #fff;border-right:2px solid #fff;transform:rotate(45deg)}
</style>
